def hack():
    if request.method == "POST":
        url = request.form["url"]
        user = request.form["user"]
        realm = request.form["realm"]

        if not re.match("^[a-zA-Z0-9-]+", url):
            return "Invalid URL"
        if not re.match("^[a-zA-Z0-9-]+", user):
            return "Invalid username"
        if not re.match("^[a-zA-Z0-9-]+", realm):
            return "Invalid realm"
        if len(url) > 200 or len(user) > 200 or len(realm) > 200:
