import re

def quantify_photos_by_keywords(photos):
    keyword_counts = {}
    for photo in photos:
        keywords = [word.lower() for word in re.findall(r'[a-z0-9]+', photo['capture_text'])]
        for keyword in keywords:
            if keyword in keyword_counts:
                keyword_counts[keyword] += 1
            else:
                keyword_counts[keyword] = 1

    return keyword_counts

