import requests
from bs4 import BeautifulSoup

def is_safe(url):
    return re.match(r'^https?://[^\s]+$', url)

def get_sitemap(url):
    if not is_safe(url):
        return []
    try:
        res = requests.get(url)
        html = res.text
        soup = BeautifulSoup(html, 'html.parser')
        sitemap = soup.find_all('loc')
        return [loc.get_text() for loc in sitemap]
    except:
        return []

